using System;
using System.Collections.Generic;
using UnityEngine;

namespace HexQuest
{
    /// <summary>
    /// Loads sprites from Assets/Resources/Art (generated by tools/make_art.py) and caches them.
    /// Sprites are built at runtime from the PNGs using manifest.json (pixels-per-unit, pivot, 9-slice
    /// border), so no manual sprite import settings are needed. A missing file falls back to a plain
    /// procedural shape instead of crashing.
    /// </summary>
    public static class Art
    {
        [Serializable] class Entry
        {
            public string name; public float ppu = 100f; public float px = 0.5f, py = 0.5f;
            public int[] border; public int w, h;
        }
        [Serializable] class Manifest { public List<Entry> sprites = new List<Entry>(); }

        static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();
        static readonly HashSet<string> warned = new HashSet<string>();
        static Dictionary<string, Entry> entries;

        static void EnsureManifest()
        {
            if (entries != null) return;
            entries = new Dictionary<string, Entry>();
            var text = Resources.Load<TextAsset>("Art/manifest");
            if (text == null)
            {
                Debug.LogWarning("HexQuest: Assets/Resources/Art/manifest.json not found - using placeholder shapes.");
                return;
            }
            var m = JsonUtility.FromJson<Manifest>(text.text);
            foreach (var e in m.sprites) entries[e.name] = e;
        }

        public static bool Has(string name)
        {
            EnsureManifest();
            return entries.ContainsKey(name);
        }

        public static Sprite Get(string name)
        {
            Sprite cached;
            if (cache.TryGetValue(name, out cached) && cached != null) return cached;
            EnsureManifest();

            Texture2D tex = Resources.Load<Texture2D>("Art/" + name);
            if (tex == null)
            {
                var sp = Resources.Load<Sprite>("Art/" + name);
                if (sp != null) tex = sp.texture;
            }
            if (tex == null)
            {
                if (warned.Add(name)) Debug.LogWarning("HexQuest: missing art '" + name + "', using a placeholder.");
                var fb = Fallback(name);
                cache[name] = fb;
                return fb;
            }

            Entry e;
            entries.TryGetValue(name, out e);
            float ppu = e != null ? e.ppu : 100f;
            var pivot = e != null ? new Vector2(e.px, e.py) : new Vector2(0.5f, 0.5f);
            var border = Vector4.zero;
            if (e != null && e.border != null && e.border.Length == 4)
                border = new Vector4(e.border[0], e.border[1], e.border[2], e.border[3]);

            tex.wrapMode = name.StartsWith("water_") ? TextureWrapMode.Repeat : TextureWrapMode.Clamp;
            var s = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), pivot, ppu, 0, SpriteMeshType.FullRect, border);
            s.name = name;
            cache[name] = s;
            return s;
        }

        /// <summary>Pixel size of the source image (for aspect-correct layout), or zero if unknown.</summary>
        public static Vector2 PixelSize(string name)
        {
            EnsureManifest();
            Entry e;
            return entries.TryGetValue(name, out e) ? new Vector2(e.w, e.h) : Vector2.zero;
        }

        static Sprite Fallback(string name)
        {
            if (name.StartsWith("hex_") || name.StartsWith("ground_") || name.StartsWith("ui_hex")) return ProceduralArt.HexUi();
            if (name.StartsWith("fx_") || name == "coin" || name.StartsWith("ui_round") || name == "ui_knob") return ProceduralArt.Circle();
            if (name.StartsWith("ui_")) return ProceduralArt.RoundedRect();
            var t = Texture2D.whiteTexture;
            return Sprite.Create(t, new Rect(0, 0, t.width, t.height), new Vector2(0.5f, 0.5f), t.width);
        }
    }
}
